#!/bin/sh
# In Play mode: prints balance, hint, selected tool button, action buttons state and visible tooltip lines.
cd "$(dirname "$0")/.." || exit 1
unity command eval --code 'var Q = (System.Func<UnityEngine.UIElements.VisualElement, string, UnityEngine.UIElements.VisualElement>)((e, n) => UnityEngine.UIElements.UQueryExtensions.Q(e, n)); var r = UnityEngine.Object.FindAnyObjectByType<TrafficGame.Views.UI.GameUi>().GetComponent<UnityEngine.UIElements.UIDocument>().rootVisualElement; var t = Q(r, "tooltip"); var lines = ""; if (t.resolvedStyle.display != UnityEngine.UIElements.DisplayStyle.None) foreach (var c in t.Children()) { var l = c as UnityEngine.UIElements.Label; if (l != null && l.resolvedStyle.display != UnityEngine.UIElements.DisplayStyle.None) lines += l.text + "; "; } var selected = ""; foreach (var n in new[] { "tool-road", "tool-curve", "tool-bulldoze" }) if (Q(r, n).ClassListContains("is-selected")) selected = n; return ((UnityEngine.UIElements.Label)Q(r, "balance")).text + " | tool: " + selected + " | actions: " + Q(r, "actions").resolvedStyle.display + " confirm=" + Q(r, "confirm").enabledSelf + " undo=" + Q(r, "undo").enabledSelf + " | profile: " + ((UnityEngine.UIElements.Button)Q(r, "profile")).text + " | tooltip: " + lines + " | hint: " + ((UnityEngine.UIElements.Label)Q(r, "hint")).text;' --result-only | python3 -c "import json,sys; d=json.load(sys.stdin); print(d.get('result') or d)"
